export const AUDIO_SOURCE="/** A finite 2-adic resonator. Real displacement + velocity, 64 regions.\n * u'' + 2 gamma u' + omega0^2 (I + kappa [(1-s)Lgrid+s L2])u = F.\n * Velocity Verlet with symmetric damping; controls update without resetting u,v.\n * No claim of exact energy conservation at finite numerical step.\n */\nconst N=64, VERSION='1.0.0', SEED=20261021, SR=24000;\nconst DEFAULT={fold:0,depth:.7,tension:7,damping:.55,midi:48,pickup:0};\nconst hz=m=>440*2**((m-69)/12);\nfunction valuation2(n){if(!Number.isInteger(n)||n===0)throw Error('Diferencia entera no nula requerida');let k=0;while(n%2===0){n/=2;k++;}return k;}\nfunction distance2(i,j){return i===j?0:2**(-valuation2(i-j));}\nfunction weights(depth=.7){\n const w=new Float64Array(6);let norm=0;\n for(let k=0;k<6;k++){w[k]=2**((1+depth)*k);norm+=(32>>k)*w[k];}\n for(let k=0;k<6;k++)w[k]/=norm;return w;\n}\nfunction matrix(depth=.7,fold=1){\n const w=weights(depth),m=Array.from({length:N},()=>new Float64Array(N));\n for(let i=0;i<N;i++)for(let j=0;j<N;j++)if(i!==j){\n  const near=(Math.abs((i%8)-(j%8))+Math.abs((i>>3)-(j>>3))===1)?.25:0;\n  const a=(1-fold)*near+fold*w[valuation2(i-j)];m[i][j]=-a;m[i][i]+=a;\n }return m;\n}\nconst clamp=(v,lo,hi)=>Math.max(lo,Math.min(hi,v));\nfunction validate(p){\n const z={...DEFAULT,...p};\n for(const k of Object.keys(DEFAULT))if(!Number.isFinite(z[k]))throw Error('Parámetro no finito: '+k);\n z.fold=clamp(z.fold,0,1);z.depth=clamp(z.depth,0,2);z.tension=clamp(z.tension,.2,14);\n z.damping=clamp(z.damping,0,5);z.midi=clamp(z.midi,36,72);z.pickup=Math.round(clamp(z.pickup,0,7));return z;\n}\nclass Campana{\n constructor(sr=SR,p={}){\n  if(!Number.isFinite(sr)||sr<16000||sr>192000)throw Error('Sample rate fuera de rango');\n  this.sr=sr;this.dt=1/sr;this.q=new Float64Array(N);this.v=new Float64Array(N);this.a=new Float64Array(N);\n  this.lp=new Float64Array(N);this.sums=Array.from({length:7},(_,k)=>new Float64Array(1<<k));\n  this.left=new Float64Array(N);this.right=new Float64Array(N);\n  this.output=new Float64Array(2);\n  this.p=validate(p);this.target={...this.p};this.frame=0;this.work=0;this.maxPeak=0;this.clipped=0;\n  this.refresh();this.force();\n }\n refresh(){\n  this.w=weights(this.p.depth);this.omega=2*Math.PI*hz(this.p.midi);this.omega2=this.omega**2;\n  this.decay=Math.exp(-this.p.damping/this.sr);\n  // Fixed asymmetric stereo pickups; selected residue family moves the aperture.\n  let ln=0,rn=0;\n  for(let i=0;i<N;i++){\n   const family=i%8===this.p.pickup?1:.12;\n   this.left[i]=family*(.28+.6*Math.exp(-(((i-13)/11)**2))+.21*Math.sin(i*2.17+.4));\n   this.right[i]=family*(.25+.55*Math.exp(-(((i-46)/13)**2))+.19*Math.cos(i*1.73+.7));\n   ln+=this.left[i]**2;rn+=this.right[i]**2;\n  }\n  for(let i=0;i<N;i++){this.left[i]/=Math.sqrt(ln);this.right[i]/=Math.sqrt(rn);}\n }\n laplacian(q=this.q,out=this.lp){\n  this.sums[6].set(q);\n  for(let k=5;k>=0;k--)for(let r=0;r<(1<<k);r++)this.sums[k][r]=this.sums[k+1][r]+this.sums[k+1][r+(1<<k)];\n  const f=this.p.fold,w=this.w;\n  for(let i=0;i<N;i++){\n   let neighbours=0;\n   for(let k=0;k<6;k++)neighbours+=w[k]*this.sums[k+1][(i^(1<<k))&((1<<(k+1))-1)];\n   let grid=0;\n   if(i%8)grid+=q[i]-q[i-1];if(i%8<7)grid+=q[i]-q[i+1];\n   if(i>=8)grid+=q[i]-q[i-8];if(i<56)grid+=q[i]-q[i+8];\n   out[i]=(1-f)*grid*.25+f*(q[i]-neighbours);\n  }return out;\n }\n force(){this.laplacian();for(let i=0;i<N;i++)this.a[i]=-this.omega2*(this.q[i]+this.p.tension*this.lp[i]);}\n energy(){\n  this.laplacian();let e=0;\n  for(let i=0;i<N;i++)e+=this.v[i]**2+this.omega2*(this.q[i]**2+this.p.tension*this.q[i]*this.lp[i]);\n  return .5*e;\n }\n set(p,immediate=false){\n  this.target=validate({...this.target,...p});\n  if(immediate){const before=this.energy();this.p={...this.target};this.refresh();this.force();this.work+=this.energy()-before;}\n }\n advanceControls(){\n  const blend=1-Math.exp(-64/(this.sr*.045));let changed=false;const next={...this.p};\n  for(const k of ['fold','depth','tension','damping','midi']){\n   const d=this.target[k]-this.p[k];if(Math.abs(d)>1e-8){next[k]+=d*blend;changed=true;}\n  }\n  if(this.p.pickup!==this.target.pickup){next.pickup=this.target.pickup;changed=true;}\n  if(changed){const before=this.energy();this.p=next;this.refresh();this.force();this.work+=this.energy()-before;}\n }\n strike(zone=1,velocity=.7){\n  if(!Number.isInteger(zone)||zone<0||zone>=N||!Number.isFinite(velocity))throw Error('Golpe inválido');\n  this.v[zone]+=this.omega*clamp(velocity,0,1)*1.25;\n }\n clear(){this.q.fill(0);this.v.fill(0);this.a.fill(0);this.work=0;}\n sample(){\n  if(this.frame%64===0)this.advanceControls();\n  const h=.5*this.dt,d=this.decay;\n  for(let i=0;i<N;i++){this.v[i]=this.v[i]*d+h*this.a[i];this.q[i]+=this.dt*this.v[i];}\n  this.force();let l=0,r=0;\n  for(let i=0;i<N;i++){this.v[i]=(this.v[i]+h*this.a[i])*d;l+=this.left[i]*this.q[i];r+=this.right[i]*this.q[i];}\n  this.frame++;l*=.78;r*=.78;\n  this.maxPeak=Math.max(this.maxPeak,Math.abs(l),Math.abs(r));\n  if(Math.abs(l)>.98||Math.abs(r)>.98)this.clipped++;\n  // Output-only protection for repeated heavy strikes; state remains linear.\n  this.output[0]=clamp(l,-.98,.98);this.output[1]=clamp(r,-.98,.98);return this.output;\n }\n snapshot(){return {q:Array.from(this.q),v:Array.from(this.v),params:{...this.p},frame:this.frame};}\n}\nfunction render(score={},duration=10,sr=SR){\n if(!Number.isFinite(duration)||duration<=0||duration>180)throw Error('Duración fuera de rango');\n const e=new Campana(sr,score.initial??{}),events=[...(score.events??[])].sort((a,b)=>a.t-b.t);\n const frames=Math.round(duration*sr),l=new Float32Array(frames),r=new Float32Array(frames),snapshots=[];\n let j=0;\n for(let i=0;i<frames;i++){\n  while(j<events.length&&events[j].t*sr<=i){const ev=events[j++];if(ev.params)e.set(ev.params,ev.immediate??false);if(ev.hit!==undefined)e.strike(ev.hit,ev.vel??.7);if(ev.clear)e.clear();}\n  const y=e.sample();l[i]=y[0];r[i]=y[1];\n  if(i%(sr/20|0)===0)snapshots.push({t:i/sr,q:Array.from(e.q),params:{...e.p}});\n }\n return {left:l,right:r,snapshots,metrics:{peak:e.maxPeak,limitedFrames:e.clipped,work:e.work,energy:e.energy(),duration,sr,events:j}};\n}\n\n// Linear decomposition of the SAME two pickups before their output protection.\n// Sum of the eight apertures equals (unclipped L + unclipped R) / 2.\nfunction familySignals(q,left,right,out){\n out.fill(0);for(let i=0;i<64;i++)out[i&7]+=.39*q[i]*(left[i]+right[i]);return out;\n}\n\n// Five deterministic scores for ONE retuned resonating body, not sampled chords.\nfunction score(id,title,duration,initial){return {id,title,duration,initial,events:[]};}\nfunction note(s,t,hit,vel){s.events.push({t,hit,vel});}\nfunction change(s,t,params){s.events.push({t,params});}\nconst rain=score('porcelain-rain','Porcelain Rain',42,{fold:.06,depth:.55,tension:4.6,damping:.55,midi:60,pickup:1});\nconst rainNotes=[60,64,67,62,60,55,57,60,64,62,60,55],rainZones=[9,41,25,57,17,49];\nfor(let bar=0;bar<12;bar++){\n const base=bar*3;change(rain,base,{midi:rainNotes[bar],fold:[.06,.14,.25,.4,.62,.72,.48,.27,.12,.55,.82,.16][bar]});\n const rhythm=bar===0?[.16,1.16,2.16]:[.16,.66,1.16,1.66,2.16];\n rhythm.forEach((beat,j)=>note(rain,base+beat,rainZones[(j+bar)%6],[.39,.21,.3,.23,.31][j]));\n}\nconst garden=score('folded-garden','Folded Garden',48,{fold:.96,depth:1.6,tension:9.5,damping:.82,midi:48,pickup:5});\nconst gardenNotes=[48,48,55,53,48,50,55,48],gardenZones=[13,45,29,61,5,37,21,53];\nfor(let bar=0;bar<16;bar++){\n const base=bar*2.4;change(garden,base,{midi:gardenNotes[Math.floor(bar/2)],fold:bar<4?.96:bar<8?.5:bar<12?.83:1,depth:bar<8?1.6:1.9});\n [.14,.74,1.04,1.64,1.94,2.24].forEach((beat,j)=>note(garden,base+beat,gardenZones[(bar+j*3)%8],[.42,.24,.3,.36,.22,.27][j]));\n if(bar%4===3)note(garden,base+1.64,gardenZones[(bar+4)%8],.13);\n}\nconst tide=score('binary-tide','Binary Tide',54,{fold:1,depth:1.85,tension:11.2,damping:.24,midi:36,pickup:6});\nfor(let bar=0;bar<8;bar++){\n const base=bar*6,zone=[6,38,22,54,14,46,30,62][bar];\n change(tide,base,{midi:[36,43,41,38,36,41,43,38][bar],depth:bar%2?1.35:1.85});\n note(tide,base+.18,zone,.43);note(tide,base+2.28,zone^32,.21);note(tide,base+3.93,zone^16,.17);\n change(tide,base+1.38,{fold:bar%2?.92:.04});change(tide,base+4.38,{fold:bar%2?.15:1});\n}\nconst orchard=score('glass-orchard','Glass Orchard',50,{fold:.42,depth:1.1,tension:3.7,damping:.4,midi:64,pickup:3});\nfor(let bar=0;bar<10;bar++){\n const base=bar*4;change(orchard,base,{midi:[64,71,67,69,62,64,59,64,67,62][bar],fold:[.42,.16,.08,.37,.7,.88,.6,.28,.11,.52][bar]});\n [.18,.98,1.78,2.98].forEach((beat,j)=>note(orchard,base+beat,[3,35,19,51,11,43,27,59][(bar*2+j)%8],[.34,.22,.27,.18][j]));\n}\nconst waltz=score('afterimage-waltz','Afterimage Waltz',57,{fold:.7,depth:.85,tension:6.2,damping:.46,midi:57,pickup:2});\nfor(let bar=0;bar<22;bar++){\n const base=bar*2;change(waltz,base,{midi:[57,60,64,62,55,57,60,59,57,52,55][Math.floor(bar/2)],fold:bar<4?.7:bar<8?.18:bar<12?.5:bar<16?.94:bar<20?.35:.08});\n [.16,.8266666667,1.4933333333].forEach((beat,j)=>note(waltz,base+beat,[10,42,26,58,18,50][(bar+j*2)%6],[.36,.2,.24][j]));\n if(bar%4===3)note(waltz,base+1.8266666667,(bar*8+2)%64,.12);\n}\nconst SONGS=[rain,garden,tide,orchard,waltz].map(s=>({...s,events:s.events.sort((a,b)=>a.t-b.t)}));\nfunction songById(id){return SONGS.find(s=>s.id===id);}\n\n// Concatenated after the byte-frozen engine and deterministic score definitions.\nclass SculptureProcessor extends AudioWorkletProcessor{\n constructor(){\n  super();this.e=new Campana(sampleRate);this.queue=[];this.squares=new Float64Array(64);this.count=0;this.hits=0;this.song=null;this.songFrame=0;this.playing=false;this.ended=false;this.fade=null;this.apertureSamples=new Float64Array(8);\n  this.port.onmessage=({data:m})=>{\n   if(m.type==='params'){if(m.cancel)this.cancelScore();this.e.set(m.params);}\n   if(m.type==='hit')this.strike(m.region,m.velocity??.72);\n   if(m.type==='clear'){this.cancelScore();this.e.clear();this.squares.fill(0);this.count=0;this.fade=null;}\n   if(m.type==='play'){const s=songById(m.id);if(s){this.playing=false;this.fade={left:Math.round(sampleRate*.025),total:Math.round(sampleRate*.025),next:s};}}\n   if(m.type==='pause'&&this.song&&!this.ended)this.playing=false;\n   if(m.type==='resume'&&this.song&&!this.ended)this.playing=true;\n   if(m.type==='stop'){this.cancelScore();this.fade={left:Math.round(sampleRate*.025),total:Math.round(sampleRate*.025),next:null};}\n  };\n }\n cancelScore(){this.song=null;this.playing=false;this.ended=false;this.queue=[];this.fade=null;}\n strike(region,velocity){this.e.strike(region,velocity);this.hits++;this.port.postMessage({type:'strike',region,frame:this.e.frame,velocity});}\n start(s){\n  this.e.clear();this.squares.fill(0);this.count=0;this.e.set(s.initial,true);this.song=s;this.songFrame=0;this.playing=true;this.ended=false;\n  this.queue=s.events.map(ev=>({...ev,frame:Math.round(ev.t*sampleRate)}));\n }\n process(input,outputs){\n  const out=outputs[0];if(!out?.[0])return true;\n  for(let j=0;j<out[0].length;j++){\n   if(this.playing&&this.song){\n    while(this.queue.length&&this.queue[0].frame<=this.songFrame){const ev=this.queue.shift();if(ev.params)this.e.set(ev.params);if(ev.hit!==undefined)this.strike(ev.hit,ev.vel??.5);}\n    this.songFrame++;if(this.songFrame>=Math.round(this.song.duration*sampleRate)){this.playing=false;this.ended=true;}\n   }\n   const y=this.e.sample();let level=1;\n   if(this.fade){level=this.fade.left/this.fade.total;this.fade.left--;if(this.fade.left<=0){const next=this.fade.next;this.fade=null;if(next)this.start(next);else{this.e.clear();this.squares.fill(0);this.count=0;}level=0;}}\n   out[0][j]=y[0]*level;if(out[1])out[1][j]=y[1]*level;\n   if(outputs.length>1){familySignals(this.e.q,this.e.left,this.e.right,this.apertureSamples);for(let k=0;k<8;k++)if(outputs[k+1]?.[0])outputs[k+1][0][j]=this.apertureSamples[k]*level;}\n   for(let k=0;k<64;k++)this.squares[k]+=this.e.q[k]**2;this.count++;\n  }\n  if(this.count>=1024){\n   const rms=Array.from(this.squares,v=>Math.sqrt(v/this.count));\n   this.port.postMessage({type:'state',rms,params:{...this.e.p},energy:this.e.energy(),frame:this.e.frame,hits:this.hits,peak:this.e.maxPeak,limitedFrames:this.e.clipped,transport:this.song?{id:this.song.id,elapsed:this.songFrame/sampleRate,duration:this.song.duration,playing:this.playing,ended:this.ended}:null});this.squares.fill(0);this.count=0;\n  }\n  return true;\n }\n}\nregisterProcessor('otra-distancia',SculptureProcessor);\n";
